//! Minimal builtin redirect resources for the adblock engine.
//!
//! Only resources that are fully generated and byte verified are shipped:
//! transparent 1x1 and 32x32 PNGs plus a transparent 1x1 GIF. Rules that
//! redirect to other resource names still block the request; they simply
//! substitute no body. Nothing that can execute is ever included.

use adblock::resources::{MimeType, PermissionMask, Resource, ResourceType};

const PNG_1X1: &str = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAAEElEQVR4AQEABf/6AAAAAAAABQABdoo2PQAAAABJRU5ErkJggg==";
const PNG_32X32: &str = "";
const GIF_1X1: &str = "R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";

fn image(name: &str, mime: MimeType, content: &str) -> Resource {
    Resource {
        name: name.to_owned(),
        aliases: Vec::new(),
        kind: ResourceType::Mime(mime),
        content: content.to_owned(),
        dependencies: Vec::new(),
        permission: PermissionMask::default(),
    }
}

/// The builtin resource set: transparent images usable by $redirect rules
/// plus an empty noop text resource.
pub fn builtin_resources() -> Vec<Resource> {
    vec![
        image("1x1.gif", MimeType::ImageGif, GIF_1X1),
        image("1x1.png", MimeType::ImagePng, PNG_1X1),
        image("32x32.png", MimeType::ImagePng, PNG_32X32),
        image("noop.txt", MimeType::TextPlain, ""),
    ]
}
